#include <bits/stdc++.h>
using namespace std;

vector<int> nearest_smaller(const vector<long long>& a) {
    vector<int> previous(a.size(), 0);
    vector<int> candidates;

for (int i = 0; i < static_cast<int>(a.size()); ++i) {
    while (!candidates.empty() && a[candidates.back()] >= a[i]) {
        candidates.pop_back();
    }
    if (!candidates.empty()) {
        previous[i] = candidates.back() + 1;
    }
    candidates.push_back(i);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> a(n);
    for (long long& value : a) {
        cin >> value;
    }
    vector<int> previous = nearest_smaller(a);
    for (int i = 0; i < n; ++i) {
        if (i > 0) {
            cout << ' ';
        }
        cout << previous[i];
    }
    cout << '\n';
}

